import { drizzle } from "drizzle-orm/d1";
import { env } from "cloudflare:workers";
import { posts } from "@/db/schema";

export const BlogIndex = async () => {
  const db = drizzle(env.DB);
  const allPosts = await db.select().from(posts).all();

  return (
    <main>
      <h1>Blog</h1>
      {allPosts.length === 0 ? (
        <p>No posts yet.</p>
      ) : (
        <ul>
          {allPosts.map((post) => (
            <li key={post.id}>
              <a href={`/blog/${post.slug}`}>{post.title}</a>
            </li>
          ))}
        </ul>
      )}
    </main>
  );
};

import { drizzle } from "drizzle-orm/d1";
import { eq } from "drizzle-orm";
import { env } from "cloudflare:workers";
import { posts } from "@/db/schema";

export const BlogPost = async ({ slug }: { slug: string }) => {
  const db = drizzle(env.DB);
  const results = await db
    .select()
    .from(posts)
    .where(eq(posts.slug, slug))
    .all();

  const post = results[0];

  if (!post) {
    return null;
  }

  return (
    <main>
      <h1>{post.title}</h1>
      <article>{post.content}</article>
      <p>
        <a href="/blog">← Back to blog</a>
      </p>
    </main>
  );
};

import { render, route } from "rwsdk/router";
import { defineApp } from "rwsdk/worker";

import { Document } from "@/app/document";
import { setCommonHeaders } from "@/app/headers";
import { Home } from "@/app/pages/home";
import { BlogIndex } from "@/app/pages/blog/BlogIndex";
import { BlogPost } from "@/app/pages/blog/BlogPost";

export type AppContext = {};

export default defineApp([
  setCommonHeaders(),
  ({ ctx }) => {
    // setup ctx here
    ctx;
  },
  render(Document, [
    route("/", Home),
    route("/blog", () => <BlogIndex />),
    route("/blog/:slug", async ({ params }) => {
      const content = await BlogPost({ slug: params.slug });
      if (!content) {
        return new Response("Post not found", { status: 404 });
      }
      return content;
    }),
  ]),
]);
